"""Writes the author's manually reasoned first dossier, NOT a classifier or judge."""
import json
from pathlib import Path
w=Path(__file__).parent
cases=json.loads((w/'challenge.json').read_text());out=[]
def row(i,boundary,items,unsupported):
 c=cases[i-1];a={}
 for metric,value,fragments,reason,*missing in items:
  assert all(f in c['scenario'] for f in fragments),(i,metric,fragments)
  a[metric]={'value':value,'evidence':fragments,'reasoning':reason,'missing':missing[0] if missing else []}
 out.append({'id':c['id'],'assessments':a,'system_boundary':boundary,'unsupported_conclusions':unsupported})
def no_sub(fragment,why):
 return [(m,'N',[fragment],f'S092 Impact Metrics and Table{t}: {why} Therefore no additional subsequent-system {dim} loss is supported; effects inside the vulnerable system belong to its impact set, not this metric.') for m,t,dim in [('SC',7,'confidentiality'),('SI',9,'integrity'),('SA',11,'availability')]]
row(1,'The maintenance service is the vulnerable system; the scenario expressly excludes consequences to any other system.',[
 ('PR','H',['already holds the service administrator role, with full access to its settings and files'],'S092 PR/Table4: full administrative authority is a prerequisite to reaching the flaw, rather than merely an outcome. Hence H.'),
 ('UI','N',['no other person participates'],'S092 UI/Table5: direct attacker invocation alone requires no distinct human user.')]+no_sub('No other system suffers any consequence.','The scenario explicitly confines all three types of consequence to the maintenance service.'),['Execution gained does not independently establish an additional confidentiality/integrity loss beyond preexisting administration.','No total score or bounty entitlement is established.'])
row(2,'The flawed service and payroll are distinct systems: payroll has a separately functioning role and its own security policies.',[
 ('PR','L',['after manual approval','only that person’s own settings and documents'],'S092 PR/Table4: owner-approved ordinary-account access is the prior requirement. Service-wide administration is gained afterward, so it cannot turn this into PR:H; no self-service exception is supported.'),
 ('UI','N',['performed entirely by the attacker'],'S092 UI/Table5: no separate human participation is required.'),
 ('SC','N',['No payroll information becomes readable'],'S092 Impact Metrics/Table7: the scenario rules out an added disclosure in payroll; write capability alone does not establish read capability.'),
 ('SI','H',['overwrite every protected record','a separately functioning payroll system with its own security policies'],'S092 Table9: complete modification control over protected records of an independently functioning system establishes subsequent integrity H.'),
 ('SA','N',['payroll service availability is unchanged'],'S092 Table11: unchanged availability means no added subsequent availability impact; do not infer disruption from overwrite authority.')],['Post-exploit administrator gain is not prior PR:H.','Overwriting records does not itself justify assumed disclosure or service outage.'])
row(3,'All consequences are inside the vulnerable workspace service, regardless of the attacker-owned workspace role.',[
 ('PR','N',['unrestricted self-service signup and grant themselves the owner role as part of the attack','no approval, preexisting account, invitation, or privileged credential needed'],'S092 PR guidance: these facts establish the self-service exception. Owner is an attacker-provisioned role during the attack, not privileged access that must already be held.'),
 ('UI','N',['invoked by the attacker alone'],'S092 Table5: signup and invocation are attacker actions; no other human must participate.')]+no_sub('all consequences confined to that service and none to another system','The scenario explicitly rules out external consequences.'),['The string owner is not sufficient reason for PR:H.','Confidential workspace disclosure may affect vulnerable-system confidentiality, but not SC here.'])
row(4,'The feed is vulnerable; the directory is a subsequent system because it functions separately and has its own policies.',[
 ('PR','N',['An unauthenticated attacker places content'],'S092 Table4: no attacker account or prior authority is needed; victim rights are not attacker privileges.'),
 ('UI','P',['mere page rendering automatically triggers the flaw','without a prompt, special import, deliberate payload execution, or bypass of protections'],'S092 Table5: another user must view the page, so UI is not N. Routine automatic processing without conscious special interaction/protection override fits passive, not active.'),
 ('SC','L',['small, fixed set of restricted, low-sensitivity profile fields','no direct serious consequence to that directory'],'S092 Table7: an actual restricted disclosure occurs, so not N; bounded loss without serious consequence supports L, not H.'),
 ('SI','N',['Nothing in the directory is modified'],'S092 Table9: no added subsequent integrity loss is stated, explicitly excluding modification.'),
 ('SA','N',['its availability is unaffected'],'S092 Table11: the directory suffers no availability loss.')],['Viewing is necessary participation, so UI:N would erase the victim step.','No evidence supports H for directory disclosure.'])
row(5,'The import tool is vulnerable; the finance service has independent function and policies and is subsequent.',[
 ('PR','N',['The attacker has no account or privileges.'],'S092 Table4 and PR social-engineering guidance: authority of the targeted user is not prior attacker authority.'),
 ('UI','A',['consciously to select the attacker’s file, choose a special import mode, and dismiss a security warning'],'S092 Table5: the necessary special import and warning dismissal are conscious victim interactions and protection override; not passive rendering.'),
 ('SC','N',['No finance data is disclosed'],'S092 Table7: a payment redirection does not imply disclosure, and disclosure is explicitly absent.'),
 ('SI','H',['changes the sole authoritative payment destination','direct serious consequence to the finance service'],'S092 Table9: one field can qualify for H where its malicious alteration directly causes serious consequence. The explicit theft-causing authoritative change supplies that basis despite limited modification scope.'),
 ('SA','N',['no service is interrupted'],'S092 Table11: serious financial integrity impact is not evidence of availability loss; interruption is explicitly absent.')],['One modified field does not automatically mean low integrity impact.','No full CVSS score, financial-loss amount or bounty follows.'])
row(6,'Display plus exclusive supporting database form the single vulnerable system of interest: coherent service, shared policies, no independent database function. Different company ownership does not override those facts.',[
 ('PR','N',['An attacker without authentication sends a request'],'S092 Table4: no prior attacker authority is required.'),
 ('UI','N',['without any other human participation'],'S092 Table5: only the attacker acts.')]+no_sub('No consequence occurs outside this combined product-and-database system.','S092 system-of-interest guidance groups exclusive supporting components. Disclosure and settings changes remain in that combined vulnerable system, despite another company operating the database.'),['Different company ownership is not enough to assign subsequent impact.','Complete database disclosure is not SC:H within the stipulated combined boundary.'])
row(7,'The relay is vulnerable; the separately functioning archive with its own policies is subsequent.',[
 ('PR','L',['manually approved ordinary user account, limited to that user’s own non-sensitive resources'],'S092 Table4: this is prerequisite low authority, not unrestricted self-service and not administration.'),
 ('UI','N',['needs no other person’s action'],'S092 Table5: the attacker can perform the exploit without another user.'),
 ('SC','H',['its private decryption key, which directly compromises the confidentiality of its protected archives'],'S092 Table7: the loss is only one secret by count but directly serious by capability/consequence, satisfying the H alternative. The private key and explicit archive confidentiality compromise support H rather than a cardinality-based L.'),
 ('SI','N',['no modification or availability loss occurs'],'S092 Table9: the established outcome is confidentiality only; no additional modification is supported.'),
 ('SA','N',['no modification or availability loss occurs'],'S092 Table11: no service loss occurs; possession of a decryption key does not itself establish denial.')],['A single secret does not force SC:L.','Do not add hypothetical write access or service disruption from key possession.'])
row(8,'The gateway is named as vulnerable, but the partner’s independent function/security-policy relationship is unknown; a subsequent-system boundary cannot yet be established.',[
 ('PR','insufficient',['does not say whether the attacker needs an account, what rights any account has'],'S092 PR/Table4 requires prior authority facts; remote access alone does not settle N/L/H.',['Is prior authenticated authority required, with what rights, and can the attacker self-provision it?']),
 ('UI','insufficient',['whether a different user must participate'],'S092 UI/Table5 cannot distinguish attacker-only operation from passive or active victim participation without the required action sequence.',['Must another human act, and is the action ordinary rendering, a specific conscious operation, or a protection override?']),
 ('SC','insufficient',['how the gateway and partner service divide their functions or security policies','what information, modifications, or interruption successful exploitation can cause'],'S092 system-of-interest and Table7: neither an independent subsequent boundary nor additional disclosure/seriousness is established; silence is not N.',['Is the partner functionally/policy independent or exclusive support, and what additional restricted data can actually be disclosed with what direct consequence?']),
 ('SI','insufficient',['how the gateway and partner service divide their functions or security policies','what information, modifications, or interruption successful exploitation can cause'],'S092 system-of-interest and Table9: need a subsequent boundary and supported modification consequence; the word affect cannot discriminate N/L/H.',['What is the partner’s relationship to the gateway, and what additional modification is possible, to what extent and with what serious consequence?']),
 ('SA','insufficient',['how the gateway and partner service divide their functions or security policies','what information, modifications, or interruption successful exploitation can cause'],'S092 system-of-interest and Table11: neither external loss nor its duration/extent is known. Remote issue does not establish service outage.',['Does the independent partner lose availability, and can repeated exploitation cause complete sustained/persistent denial or another direct serious consequence?'])],['Remote does not imply PR:N or UI:N.','May affect is not proof of SC/SI/SA impact or an independent system.','Insufficient is workflow abstention, not a vector X or N.'])
row(9,'The scheduler is vulnerable; document search is subsequent by independent function and security policies.',[
 ('PR','N',['accepts unauthenticated attacker requests'],'S092 Table4: no prerequisite authenticated authority.'),
 ('UI','N',['requires no other human action'],'S092 Table5: no separate participant is required.'),
 ('SC','N',['There is no disclosure or modification in the search service'],'S092 Table7: disclosure is explicitly absent, rather than merely omitted.'),
 ('SI','N',['There is no disclosure or modification in the search service'],'S092 Table9: modification is explicitly absent.'),
 ('SA','L',['run slower','Even repeated attacks cannot deny legitimate users service completely','slowdown has no direct serious consequence'],'S092 Table11: actual degraded performance establishes loss, but inability to deny service completely even with repetition and lack of serious consequence support L rather than H.')],['A service slowdown is not automatically H.','No disclosure or modification can be inferred from degraded performance.'])
row(10,'Monitoring is vulnerable; the independently functioning analytics service with its own policies is subsequent. Prior analytics access matters to the impact delta, not to redefining the vulnerable-system boundary.',[
 ('PR','L',['ordinary, manually approved account in a monitoring service with access only to that user’s settings'],'S092 Table4: limited prior rights in monitoring are required. Existing read-only analytics access does not establish administrative control of the vulnerable service.'),
 ('UI','N',['Acting alone'],'S092 Table5: no other human is required.'),
 ('SC','N',['already has read-only access to every record','gains no additional access to analytics information'],'S092 Impact Metrics/Table7: confidentiality impact measures additional loss from this exploit. All-record read access is preexisting and unchanged; counting it again as SC:H would double-count prior access.'),
 ('SI','N',['cannot modify its data'],'S092 Table9: no added integrity loss is possible under the stated outcome.'),
 ('SA','H',['sustain complete denial of the analytics service to all legitimate users for as long as the attack continues'],'S092 Table11: complete denial sustained during continuing attack qualifies as H; persistence after stopping is not required for this alternative.')],['Existing full read access does not itself create a new SC impact.','No post-attack persistence requirement should erase sustained complete denial.'])
assert len(out)==10
(w/'first-answers.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('manual-assessments-written=10 metrics=50; exact-fragment assertions pass; NOT semantic verification')
